IDENTITY_FILES = ['cex/hp/unified_pac_planner.py', 'cex/hp/pac_actions.py', 'cex/hp/joint_stream.py', 'cex/hp/joint_proposal.py', 'cex/hp/joint_witness.py', 'cex/hp/joint_optimize.py', 'cex/hp/check_joint.py', 'cex/hp/global_stream.py', 'cex/hp/global_circuit.py', 'cex/hp/global_optimize.py', 'cex/hp/check_global.py', 'cex/hp/lifted_decoder.py', 'cex/hp/grouped_envelope.py', 'cex/hp/residual_max_envelope.py', 'cex/hp/unified_planner.py', 'cex/hp/coarse_envelope.py', 'cex/hp/cost_model.py', 'cex/hp/PHASE_RATES_R1.json', 'cex/blockres/integrated.py', 'cex/blockres/blockres.py', 'cex/newarm/cex_executor.py', 'cex/newarm/cex_kernel.cpp', 'cex/newarm/libcex_kernel.dylib', 'cex/newarm/cex_build.json']
ARM_ARGS = {'REPAIRED': ['--lifted', '--envelope', 'RMAX'], 'SEED': ['--lifted', '--envelope', 'RMAX', '--global', 'seed'], 'GLOBAL': ['--lifted', '--envelope', 'RMAX', '--global', 'global'], 'OLD_POLICY_REPAIRED': ['--lifted', '--envelope', 'RMAX', '--old-policy'], 'G0_GLOBAL': ['--lifted', '--envelope', 'RMAX', '--global', 'g0_global'], 'CAP_ONLY': ['--lifted', '--envelope', 'RMAX', '--global', 'cap_only'], 'MOMENT_ONLY': ['--lifted', '--envelope', 'RMAX', '--global', 'moment_only'], 'FORCED_SEED': ['--force-stream', 'global', '--global', 'seed'], 'FORCED_GLOBAL': ['--force-stream', 'global', '--global', 'global']}
DIAGNOSTIC_ARMS = ('OLD_POLICY_REPAIRED', 'G0_GLOBAL', 'CAP_ONLY', 'MOMENT_ONLY', 'FORCED_SEED', 'FORCED_GLOBAL')
def sha(p): return hashlib.sha256(open(p, 'rb').read()).hexdigest()
def identity(code_root): return {f: sha(os.path.join(code_root, 'code', f)) for f in IDENTITY_FILES}

def cmd_of(arm, model, out, c, seed, root):
    b = FROZEN['base']; code = os.path.join(root, 'code')
    if arm == 'BASE': return [PY, os.path.join(code, 'cex/blockres/integrated.py'), '--input', model, '--output', out, '--budget', str(c['hard']), '--mb-cap', str(b['mb_cap']), '--table-cap', str(b['table_cap']), '--enum-cap', str(b['enum_cap']), '--schedule', b['schedule'], '--route', b['route'], '--proposal', b['proposal'], '--batch', str(b['batch']), '--seed', str(seed), '--epsilon', FROZEN['epsilon'], '--delta', FROZEN['delta']]
    base = [PY, os.path.join(code, 'cex/hp/unified_pac_planner.py'), '--input', model, '--output', out, '--budget', str(c['hard']), '--admission-stop', str(c['work']), '--epsilon', FROZEN['epsilon'], '--delta', FROZEN['delta'], '--seed', str(seed)]
    return base + ARM_ARGS[arm]

def sample_seed(model_sha256, k):
    """the frozen sample-seed rule (PROTOCOL section 3): first eight SHA-256 bytes of 'DGP6-SAMPLE|<model_sha256>|<k>' as an unsigned big-endian integer, reduced to the CLI's domain 1..2^31-1"""
    x = int.from_bytes(hashlib.sha256(('DGP6-SAMPLE|%s|%d' % (model_sha256, k)).encode('utf-8')).digest()[:8], 'big'); return (x % ((1 << 31) - 1)) + 1

def arm_rotation(model_sha256, n): return int(model_sha256[:8], 16) % n

def last_receipt(ledger, job):
    rows = [json.loads(l) for l in open(ledger)]; r = [x for x in rows if x.get('kind') == 'RECEIPT' and x['job'] == job]; return r[-1] if r else None

def direct_summary(s):
    """the direct-proposal (joint / global) stream summary of one planner stream record"""
    j = s.get('joint') or {}; m = s.get('mechanism') or {}; sd = m.get('seed') if isinstance(m.get('seed'), dict) else {}
    atts = []
    for a in j.get('attempts', []):
        atts.append({k: a.get(k) for k in ('index', 'kind', 'status', 'why', 'label', 'promoted', 'witness_only', 'winner', 'comparator', 'committed_epoch', 'seconds', 'started_offset_s', 'ended_offset_s', 'optimizer_failure', 'eta', 'baselines', 'forecast', 'pre_forecast', 'admission', 'quantization', 'payback', 'graph', 'float_seed', 'reference')} | dict(plans={k: {kk: (a.get('plans') or {}).get(k, {}).get(kk) for kk in ('n_nodes', 'n_reductions', 'max_splits', 'work_cells', 'peak_entries', 'n_params', 'float_tape_bytes', 'compact_peak_bytes', 'sha256')} for k in ('cap', 'moment')} if a.get('plans') else None, optimizer=({k: (a.get('optimizer') or {}).get(k) for k in ('seconds', 'evaluations', 'cache_hits', 'phases', 'endpoint')} if a.get('optimizer') else None), segment_best=((a.get('segment') or {}).get('best')), segment_points=[{k: x.get(k) for k in ('i', 'lam', 'logB', 'logS', 'logJ', 'censored')} for x in (a.get('segment') or {}).get('points', [])], certification=a.get('certification'), candidates=a.get('candidates')))
    return dict(kind=s.get('kind'), mode=j.get('global_mode') or j.get('mode'), objective=j.get('objective'), stage=s.get('stage'), closed=s.get('closed'), draws=s.get('draws'), published=s.get('published'), epochs=[{k: e.get(k) for k in ('index', 'reason', 'draws_from', 'draws_to', 'eps_num_epoch', 'eps_num_certificate_after', 'cert_t_at_commit', 'committed_offset_s', 'fingerprint', 'predecessor', 'live_joint_bytes', 'storage_released_bytes')} | dict(proposal={k: e['proposal'].get(k) for k in ('sha256', 'log2_B_W0', 'log2_S_W0sq', 'conditionals', 'provenance', 'bytes')}, constants={k: (e.get('constants') or {}).get(k) for k in ('B_eff_log2', 'eps_num', 'rho_X', 'rho_cap', 'cap_tol', 'cap_units')}, Z_epoch=e.get('Z_over_cap_EB_DIAGNOSTIC_epoch')) for e in j.get('epochs', [])],
                current_epoch=j.get('current_epoch'), epoch_switches=j.get('epoch_switches'), attempts=atts, pilot=j.get('pilot'), promotion=j.get('promotion'), activation=j.get('activation'), graph=j.get('graph'), refinement_ended=j.get('refinement_ended'), joint_bytes=j.get('joint_bytes'), allowance=j.get('allowance'), epoch_weight_statistics=j.get('epoch_weight_statistics'), seed={k: sd.get(k) for k in ('seconds', 'stages_done', 'stages_total', 'max_splits', 'work_cells', 'consumed_messages', 'peak_owned_bytes', 'owned_bytes', 'zero_rows', 'checker', 'absent_sum_scalars', 'plan_groups')}, elimination=m.get('elimination'), eps_num=m.get('eps_num'), cap_units=m.get('cap_units'), widening_parts=m.get('widening_parts'), construction_defect=m.get('construction_defect'), candidate_defect=m.get('candidate_defect'), internal_error=m.get('internal_error'), close_release=m.get('close_release'))

def summarize(arm, out, rc, c):
    from fractions import Fraction as F
    row = dict(receipt_wall_s=(rc['wall_s'] if rc else None), receipt_outcome=(rc['outcome'] if rc else None), peak_MiB=((rc['peak_tree_rss_bytes'] / 2 ** 20) if rc and rc.get('peak_tree_rss_bytes') else None))
    try:
        d = json.load(open(out)); m = d.get('mechanism') or {}
        row.update(outcome=d.get('outcome'), guarantee=d.get('guarantee'), published=d.get('published'), K=d.get('K'), solver_wall_s=d.get('wall_s'), termination=m.get('termination'), route=m.get('route'), peak_rss_bytes=d.get('peak_rss_bytes'), positive_mass_witness=(d.get('positive_mass_witness') if arm == 'BASE' else m.get('positive_mass_witness')), hard_deadline_respected=d.get('hard_deadline_respected'), version=(d.get('version') or '')[:60])
        rows_ = d.get('answers') or []; ws = [float(F(r['hi']) - F(r['lo'])) / 2 for r in rows_ if r['guarantee'] != 'NOT_PUBLISHED']
        if arm == 'BASE': row.update(base=dict(draws=m.get('draws'), Kq=m.get('Kq'), remaining=m.get('remaining'), max_remaining_width=m.get('max_remaining_width'), median_remaining_width=m.get('median_remaining_width'), X_mean=m.get('X_mean'), ESS=m.get('ESS'), zero_weight_fraction=m.get('zero_weight_fraction'), largest_share=m.get('largest_share'), eps_num=m.get('eps_num'), mb_cap=m.get('mb_cap'), mb_splits=m.get('mb_splits'), batch_used=m.get('batch_used'), deadline_phase=d.get('deadline_phase'), refusal=d.get('refusal'), trace=d.get('trace'), phases=d.get('phases_s'), structural={k: (m.get(k) or {}).get('status') for k in ('evidence_expansion', 'layered_contraction', 'ancestral_response', 'support_closure')}), radius_report=dict(worst=(max(ws) if ws else None), covered_at_eps=sum(1 for w in ws if w <= 0.005), published=len(ws), K=d.get('K')))
        else: row.update(upac=dict(streams=[{k: s.get(k) for k in ('kind', 'label', 'stage', 'closed', 'delta_s', 'scale_to_original', 'Z_original', 'draws', 'zero_draws', 'batches', 'abandoned', 'checkpoints', 'witness', 'published', 'K', 't_prep', 't_sample', 't_cert', 'X_mean', 'zero_weight_fraction', 'ESS_DIAGNOSTIC', 'largest_share', 'max_log2_X_observed', 'max_remaining_width', 'retained_bytes', 'pooled_weight_statistics')} | dict(valid_endpoints=(s.get('trace') or [{}])[-1].get('valid_endpoints') if s.get('trace') else None, mechanism={k: v for k, v in (s.get('mechanism') or {}).items() if k in ('eps_num', 'rho_cap', 'rho_X', 'alpha_per_coordinate', 'cap_log2_total', 'cap_units', 'grouped_envelope', 'rmax', 'rmax_refusal', 'rmax_allowance', 'bound_kind', 'kappa_compact', 'kappa_log2_hi', 'mb_cap', 'mb_splits', 'Kq', 'batch_used', 'terminal', 'exact_route', 'memory_policy', 'proposal_immutable', 'coarse_cards', 'widening', 'widening_parts', 'certificate_defect', 'const_log2', 'close_release')}, direct=(direct_summary(s) if s.get('kind') in ('joint', 'global') else None), trace=s.get('trace'), measurements=[x for x in (s.get('measurements') or []) if x.get('kind') in ('pac_stage', 'lifted_stage', 'joint_stage', 'joint_action')]) for s in d.get('streams', [])], risk_ledger=d.get('risk_ledger'), conflicts=d.get('conflicts'), checkpoints=d.get('checkpoints'), radius_report=d.get('radius_report'), cost_breakdown=d.get('cost_breakdown'), decisions=[{k: x.get(k) for k in ('chosen', 't_s', 'W_s', 'primary_protected', 'why')} | dict(streams=[(s_.get('label'), s_.get('forecast_s'), s_.get('draws')) for s_ in (x.get('streams') or [])], joint_offer=x.get('joint_offer')) for x in d.get('decisions', [])], joint_offer=m.get('joint_offer'), scheduling_policy=m.get('scheduling_policy'), E=m.get('exploration_account_s'), E_used=m.get('exploration_used_s'), refusal=m.get('refusal'), defect=m.get('defect'), structural=m.get('structural_info'), representations_solved=m.get('representations_solved'), native_attempts=m.get('native_attempts'), live_memory=m.get('live_memory_named_bytes'), lift_only=m.get('lift_only_candidates'), forced=d.get('forced_stream'), joint_mode=d.get('joint_mode'), global_mode=d.get('global_mode'), old_policy=d.get('old_policy'), actions=[{k: a.get(k) for k in ('action', 't_s', 'actual_s', 'status', 'result', 'stream', 'stage', 'closed', 'allowance_s', 'promoted', 'witness_only', 'winner', 'reason', 'draws', 'batches', 'forecast_s', 'label', 'kind', 'why', 'evaluations', 'graph')} for a in d.get('actions', []) if a.get('action') in ('create_joint', 'joint_offer', 'joint_pilot', 'joint_refine', 'global_optimize', 'global_activate', 'primary_probe', 'prepare_stream', 'probe_stream', 'create_lifted', 'alias_stream')]), radius_report=d.get('radius_report'))
    except Exception as e: row.update(outcome='NO_RESULT_FILE', error=repr(e)[:200])
    row['complete'] = bool(rc and rc['outcome'] == 'COMPLETED' and rc['wall_s'] <= c['outer'] and row.get('published') is not None and row.get('K') and row['published'] == row['K'] and row.get('outcome') in ('COMPLETE', 'EXACT') and bool(row.get('positive_mass_witness')) and (row.get('hard_deadline_respected') is not False)) and arm not in DIAGNOSTIC_ARMS
    return row

def main():
    ap = argparse.ArgumentParser(); ap.add_argument('sub'); ap.add_argument('manifest'); ap.add_argument('--code-root', required=True); ap.add_argument('--arms', default='BASE,REPAIRED,SEED,GLOBAL'); ap.add_argument('--contract', default='main', choices=list(CONTRACTS)); ap.add_argument('--confirm', action='store_true'); ap.add_argument('--seed-index', type=int, default=0); ap.add_argument('--only', default=None); ap.add_argument('--scope', default='dgp6_main'); ap.add_argument('--records', default=RD_DEFAULT); ap.add_argument('--freeze', default=None); ap.add_argument('--amendment', default=None); ap.add_argument('--skip-existing', action='store_true'); a = ap.parse_args()
    RD = a.records; man = json.load(open(a.manifest)); tasks = man['tasks']; arms = a.arms.split(','); c = CONTRACTS[a.contract]; env = dict(os.environ, OMP_NUM_THREADS='1', OPENBLAS_NUM_THREADS='1', MKL_NUM_THREADS='1', VECLIB_MAXIMUM_THREADS='1'); env.pop('PYTHONPATH', None); results = []; ledger = os.path.join(RD, 'DGP6_LEDGER.jsonl')
    root = os.path.abspath(a.code_root); head = subprocess.check_output(['git', '-C', root, 'rev-parse', 'HEAD']).decode().strip(); tree = subprocess.check_output(['git', '-C', root, 'rev-parse', 'HEAD^{tree}']).decode().strip(); dirty = subprocess.check_output(['git', '-C', root, 'status', '--porcelain', '--untracked-files=no', '--', 'code/cex', 'code/gbidi']).decode().strip()
    frozen = json.load(open(a.freeze or os.path.join(RD, 'FREEZE.json'))); amend = json.load(open(a.amendment)) if a.amendment else None; ref = (amend['code'] if amend else frozen['code']); ident0 = identity(root); assert head == ref['commit'], 'code root %s is not at the %s commit %s' % (head, 'amendment' if amend else 'frozen', ref['commit']); assert not dirty, 'code root has tracked changes: %s' % dirty[:200]; assert all(ident0[f] == ref['files'].get(f) for f in ident0), 'identity mismatch vs %s at launch: %s' % ('the amendment' if amend else 'FREEZE.json', [f for f in ident0 if ident0[f] != ref['files'].get(f)])
    kb = json.load(open(os.path.join(root, 'code/cex/newarm/cex_build.json'))); assert kb['binary_sha256'] == sha(os.path.join(root, 'code/cex/newarm/libcex_kernel.dylib')), 'kernel binary does not match its build record'
    seen = set()
    for t in tasks:
        key = (t['model_sha256'], t['evid_sha256']); assert key not in seen, 'duplicate input identity in the manifest: %s' % t['name']; seen.add(key)
    import dgp_paths
    for t in tasks: t['model'] = dgp_paths.resolve_input(t['model'], RD, t.get('model_sha256'))
    for i, t in enumerate(tasks):
        if a.only and t['name'] not in a.only.split(','): continue
        r = arm_rotation(t['model_sha256'], len(arms)); order = arms[r:] + arms[:r]
        if a.confirm: order = order[::-1]
        seed = sample_seed(t['model_sha256'], a.seed_index)
        for arm in order:
            tag = ('c%d' % a.seed_index) if a.confirm else ('p' if a.seed_index == 0 else 's%d' % a.seed_index); attempt = os.path.join(RD, a.sub, '%02d__%s__%s__%s' % (i, t['name'], arm, tag))
            if a.skip_existing and os.path.exists(os.path.join(attempt, 'cell.json')): continue
            os.makedirs(attempt, exist_ok=True); out = os.path.join(attempt, 'result.json'); cmd = cmd_of(arm, t['model'], out, c, seed, root); job = 'dgp6:%s:%s:%s:%s' % (a.sub, t['name'], arm, tag)
            ident_launch = identity(root)
            sup = [PY, '-m', 'gbidi.supervise', '--ledger', ledger, '--scope', a.scope, '--job', job, '--timeout', str(c['ceiling']), '--mem-gib', str(FROZEN['mem_gib']), '--interval', '0.05', '--cwd', os.path.join(root, 'code'), '--stdout', os.path.join(attempt, 'stdout.txt'), '--stderr', os.path.join(attempt, 'stderr.txt'), '--', CAFF, '-s'] + cmd
            subprocess.run(sup, cwd=SUP_CODE, env=env); rc = last_receipt(ledger, job); ident_done = identity(root)
            row = dict(task=t['name'], arm=arm, task_index=i, order_index=order.index(arm), confirm=a.confirm, seed=seed, seed_index=a.seed_index, seed_rule='DGP6-SAMPLE|<model_sha256>|<k> -> first 8 SHA-256 bytes big-endian -> (x mod (2^31 - 1)) + 1', arm_rotation='int(model_sha256[:8], 16) mod len(arms); reversed for confirmations', contract=a.contract, supervisor_ceiling_s=c['ceiling'], panel=t.get('panel'), family=t.get('family') or t.get('topology'), exposure=t.get('exposure'), model=t['model'], model_sha256=t.get('model_sha256'), evid_sha256=t.get('evid_sha256'), model_sha256_at_run=sha(t['model']), code_commit=head, code_tree=tree, identity_ok=all(ident_launch[f] == ref['files'].get(f) == ident_done[f] for f in ident_launch), amendment=(os.path.basename(a.amendment) if a.amendment else None), command=' '.join(cmd), job=job); row.update(summarize(arm, out, rc, c)); results.append(row)
            json.dump(dict(cell=row, identity_at_launch=ident_launch, identity_at_completion=ident_done), open(os.path.join(attempt, 'cell.json'), 'w'), indent=1, default=str)
            print(json.dumps({k: row.get(k) for k in ('task', 'arm', 'outcome', 'published', 'K', 'receipt_wall_s', 'receipt_outcome', 'complete', 'termination', 'identity_ok')} | dict(direct=[(j['direct']['stage'], j['direct']['draws'], j['direct']['epoch_switches'], [(x.get('status'), x.get('kind')) for x in j['direct']['attempts']]) for j in (row.get('upac') or {}).get('streams', []) if j.get('direct')]), default=str), flush=True)
            json.dump(dict(frozen=FROZEN, arms=arms, contract=a.contract, manifest=a.manifest, code_root=root, code_commit=head, code_tree=tree, confirm=a.confirm, seed_index=a.seed_index, only=a.only, results=results, utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())), open(os.path.join(RD, a.sub, 'RESULTS_%s_%s%s.json' % (a.contract, ('confirm_s%d' % a.seed_index) if a.confirm else ('s%d' % a.seed_index if a.seed_index != 0 else 'primary'), ('_' + a.only.replace(',', '_')[:60]) if a.only else '')), 'w'), indent=1, default=str)

if __name__ == '__main__': main()
